import {
  classificationRegistry,
  subjectRegistry,
  type TableClassification,
} from "../classification/registry.js";
import { DataClass } from "../classification/vocabulary.js";

const GENERATED_NOTE =
  "<!-- Generated by `pnpm compliance:generate`. Do not edit. CI fails if this is stale. -->";

const HEADER = [
  GENERATED_NOTE,
  "",
  "# Data map",
  "",
  "Every column Idenzy stores, with its classification, purpose and retention.",
  "Derived from the schemas, which are the source of truth (PROJECT.md 4.13.2): the Drizzle",
  "tables in Postgres, and the `analytics.` ones in ClickHouse (ADR-0013).",
  "",
  "Idenzy holds no certification. See PROJECT.md 4.13.10 for what is deliberately not done.",
  "",
];

function sortedEntries<T>(record: Readonly<Record<string, T>>): [string, T][] {
  return Object.entries(record).sort(([a], [b]) => a.localeCompare(b));
}

function countByClass(tables: readonly [string, TableClassification][]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const [, columns] of tables) {
    for (const column of Object.values(columns)) {
      counts.set(column.class, (counts.get(column.class) ?? 0) + 1);
    }
  }
  return counts;
}

function summarySection(tables: readonly [string, TableClassification][]): string[] {
  const counts = countByClass(tables);
  return [
    "## Summary",
    "",
    "| Class | Columns |",
    "|---|---|",
    ...Object.values(DataClass).map((cls) => `| ${cls} | ${counts.get(cls) ?? 0} |`),
    "",
  ];
}

function notesSection(columns: TableClassification): string[] {
  const noted = sortedEntries(columns).filter(([, c]) => c.note !== undefined);
  if (noted.length === 0) return [];
  return ["Notes:", "", ...noted.map(([name, c]) => `- \`${name}\`: ${c.note ?? ""}`), ""];
}

function tableSection(table: string, columns: TableClassification): string[] {
  const rows = sortedEntries(columns).map(([name, c]) => {
    const inExport = c.subjectField === true ? "yes" : "no";
    const isEncrypted = c.encrypted === true ? "yes" : "no";
    const erasure = c.erasure ?? "not_applicable";
    return `| \`${name}\` | ${c.class} | ${c.purpose} | ${c.retention} | ${inExport} | ${erasure} | ${isEncrypted} |`;
  });
  return [
    `## \`${table}\``,
    "",
    ...subjectSection(table),
    "| Column | Class | Purpose | Retention | In DSR export | Erasure | Encrypted |",
    "|---|---|---|---|---|---|---|",
    ...rows,
    "",
    ...notesSection(columns),
  ];
}

/**
 * Whose data this table holds and how a request reaches one person's rows (4.13.6).
 *
 * Printed above the columns because it is the question an auditor asks first and the one the
 * column list cannot answer: "you say you hold an email address for a data subject — show me how
 * you would find mine." A table with no entry holds nobody's personal data.
 */
function subjectSection(table: string): string[] {
  const subject = subjectRegistry().get(table);
  if (subject === undefined) return [];
  const located =
    subject.locatedBy === null ? "not directly addressable" : `by \`${subject.locatedBy}\``;
  return [
    `Data subject: **${subject.population}**, ${located}.`,
    ...(subject.note === undefined ? [] : ["", subject.note]),
    "",
  ];
}

/**
 * The data inventory ISO 27001 asks for, generated from the schema (PROJECT.md 4.13.2).
 *
 * Generated rather than maintained, because an inventory that drifts from the schema is
 * worse for an audit than no inventory at all.
 */
export function generateDataMap(): string {
  const tables = [...classificationRegistry().entries()].sort(([a], [b]) => a.localeCompare(b));
  const lines = [
    ...HEADER,
    ...summarySection(tables),
    ...tables.flatMap(([table, columns]) => tableSection(table, columns)),
  ];
  return `${lines.join("\n").trimEnd()}\n`;
}
